from pathlib import Path
import subprocess, base64

BASE = "7a97ab2"

head = subprocess.check_output(
    ["git", "rev-parse", "--short", "HEAD"],
    text=True,
).strip()

if head != BASE:
    raise SystemExit(
        f"Wrong baseline: HEAD is {head}, expected {BASE}."
    )

new_files = {'lib/polls/access.ts': '', 'lib/polls/notifications.ts': '', 'lib/polls/lifecycle.ts': '', 'app/(portal)/polls/actions.ts': '', 'app/(portal)/polls/page.tsx': '', 'app/(portal)/admin/polls/actions.ts': '', 'app/(portal)/admin/polls/page.tsx': ''}
mods = [('lib/auth/admin-section-access.ts', 'ICB8ICJub3RpZmljYXRpb25zIgogIHwgInVzZXJzIg==', 'ICB8ICJub3RpZmljYXRpb25zIgogIHwgInBvbGxzIgogIHwgInVzZXJzIg==', 'AdminSection polls type'), ('lib/auth/admin-section-access.ts', 'ICBub3RpZmljYXRpb25zOiBbIm93bmVyIiwgImFkbWluIiwgIm1hc3RlciJdLAogIHVzZXJzOiBbIm93bmVyIiwgImFkbWluIl0s', 'ICBub3RpZmljYXRpb25zOiBbIm93bmVyIiwgImFkbWluIiwgIm1hc3RlciJdLAogIHBvbGxzOiBbIm93bmVyIiwgImFkbWluIiwgIm1hc3RlciJdLAogIHVzZXJzOiBbIm93bmVyIiwgImFkbWluIl0s', 'Polls admin roles'), ('app/(portal)/admin/layout.tsx', 'ICAgICAgICAgICAge2Nhbigibm90aWZpY2F0aW9ucyIpID8gKAogICAgICAgICAgICAgIDxBZG1pbk5hdmlnYXRpb25MaW5rIGhyZWY9Ii9hZG1pbi9ub3RpZmljYXRpb25zIj4KICAgICAgICAgICAgICAgIE5vdGlmaWNhdGlvbnMKICAgICAgICAgICAgICA8L0FkbWluTmF2aWdhdGlvbkxpbms+CiAgICAgICAgICAgICkgOiBudWxsfQoKICAgICAgICAgICAge2Nhbigib3JkZXJzIikgPyAo', '', 'Admin Polls navigation')]

for path, payload in new_files.items():
    target = Path(path)

    if target.exists():
        raise SystemExit(
            f"Refusing to overwrite existing file: {path}"
        )

    target.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    target.write_text(
        base64.b64decode(
            payload
        ).decode("utf-8"),
        encoding="utf-8",
    )

    print("✓ created", path)

cache = {}

for path, old_b64, new_b64, label in mods:
    target = Path(path)

    if not target.exists():
        raise SystemExit(
            f"Missing {path}"
        )

    text = cache.get(
        path,
        target.read_text(
            encoding="utf-8",
        ),
    )

    old = base64.b64decode(
        old_b64
    ).decode("utf-8")

    new = base64.b64decode(
        new_b64
    ).decode("utf-8")

    count = text.count(old)

    if count != 1:
        raise SystemExit(
            f"{label}: expected 1 match, found {count}."
        )

    cache[path] = text.replace(
        old,
        new,
        1,
    )

for path, text in cache.items():
    Path(path).write_text(
        text,
        encoding="utf-8",
    )
    print("✓ updated", path)

print("")
print("Polling system code installed on baseline 7a97ab2.")
print("IMPORTANT: run polling_system_7502b07.sql in Supabase.")
print("Then run: npm run build")
